using System.Collections.Generic;
using System.IO;
using AI003.World;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.SceneManagement;

namespace AI003.EditorTools
{
    /// <summary>
    /// Scatters the model set over the world with the density rules of
    /// docs/worldview/03-art-direction.md §5.1 and bakes each species into ONE combined
    /// mesh under [AI003] Vegetation. One object per species keeps the scene diff at
    /// reference level (the geometry lives in Assets/Generated, which is regenerated by
    /// this menu) and still reproduces exactly from the world data plus the models.
    ///
    /// Rules (§5.1, do not retune here):
    ///   forest  : grass + m_block >= 0.72 + slope <= 0.55, 0.35 trees / 100 m²
    ///   steppe  : grass + m_block <= 0.62 + slope <= 0.35, 0.02 trees / 100 m²
    ///   rocks   : snow biome, and the rock band 100–255 m
    /// </summary>
    public static class AuthorVegetation
    {
        private const string RootName = "[AI003] Vegetation";
        private const string MeshDir = "Assets/Generated/Vegetation";
        private const string ModelDir = "Assets/Art/Models";
        private const string MaterialDir = "Assets/Settings/Vegetation";
        private const string TextureDir = "Assets/Settings/Textures";

        // §5.1 densities, expressed as lattice spacing so the scatter is deterministic.
        private const float ForestSpacing = 16.9f; // 0.35 trees / 100 m²
        private const float SteppeSpacing = 70.7f; // 0.02 trees / 100 m²
        private const float RockSpacing = 45f;

        private const float ForestSlope = 0.55f; // 29°
        private const float SteppeSlope = 0.35f; // 19°
        private const float NoTreeSlope = 0.70f; // 35°

        [MenuItem("AI003/Author Vegetation")]
        public static void Run()
        {
            Directory.CreateDirectory(MeshDir);

            var data = WorldData.Load(Path.Combine(Application.streamingAssetsPath, "world"));
            var moisture = WorldTheme.BuildMoistureMap(data);

            var existing = GameObject.Find(RootName);
            var root = existing != null ? existing : new GameObject(RootName);

            int conifer = 0;
            int dead = 0;
            int acaciaSmall = 0;
            int acacia = 0;
            int rock = 0;
            int rockB = 0;

            conifer = Scatter(data, moisture, root, "conifer", ForestSpacing, new Color(0.16f, 0.24f, 0.13f),
                (h, up, slope, m, hash) => IsForest(slope, m) && hash < 0.70f, out _);
            dead = Scatter(data, moisture, root, "dead_tree", ForestSpacing, new Color(0.24f, 0.19f, 0.15f),
                (h, up, slope, m, hash) => IsForest(slope, m) && hash >= 0.70f, out _);
            acaciaSmall = Scatter(data, moisture, root, "acacia_small", SteppeSpacing, new Color(0.33f, 0.30f, 0.18f),
                (h, up, slope, m, hash) => IsSteppe(slope, m) && hash < 0.92f, out _);
            // Chief's ruling: a fixed count inside the steppe anchor circle — a lattice
            // with a hash gate produced 0 then 1, never a landmark stand.
            acacia = PlaceAcacia(data, moisture, root,
                new[] { new Vector3(336f, 0f, 176f), new Vector3(423f, 0f, -203f) },
                new[] { 160f, 120f }, new[] { 60, 20 });
            // Ground cover: the steppe needs grass tufts to read as grassland, and the
            // forest floor needs tufts plus bushes. Both are alpha-cutout cards.
            int tuft = Scatter(data, moisture, root, "grass_tuft_b", 14f, new Color(0.55f, 0.50f, 0.33f),
                (h, up, slope, m, hash) => IsSteppe(slope, m), out _);
            int bush = Scatter(data, moisture, root, "bush_a", 30f, new Color(0.20f, 0.22f, 0.14f),
                (h, up, slope, m, hash) => IsForest(slope, m), out _);
            rock = Scatter(data, moisture, root, "snow_rock", RockSpacing, new Color(0.55f, 0.56f, 0.57f),
                (h, up, slope, m, hash) => (IsSnow(data, h) || IsRockBand(h)) && hash < 0.35f, out _);
            rockB = Scatter(data, moisture, root, "snow_rock_b", RockSpacing, new Color(0.48f, 0.49f, 0.50f),
                (h, up, slope, m, hash) => (IsSnow(data, h) || IsRockBand(h)) && hash >= 0.35f, out _);

            AssetDatabase.SaveAssets();
            EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
            int total = conifer + dead + acaciaSmall + acacia + rock + rockB + tuft + bush;
            Debug.Log($"[AI003][VEG] placed {total}: conifer {conifer}, dead_tree {dead}, " +
                      $"acacia_small {acaciaSmall}, acacia {acacia}, snow_rock {rock}, snow_rock_b {rockB}, " +
                      $"grass_tuft {tuft}, bush {bush} " +
                      $"under {RootName} — save the scene");
        }

        /// <summary>
        /// Batch entry: re-author only the vegetation into the saved OpenWorld scene.
        /// A still or a review run pipes this through -executeMethod so the scene keeps
        /// the same mesh GUIDs without re-baking terrain or dressing.
        /// </summary>
        [MenuItem("AI003/Author Vegetation (batch)")]
        public static void RunBatch()
        {
            var scene = EditorSceneManager.OpenScene("Assets/Scenes/OpenWorld.unity", OpenSceneMode.Single);
            Run();
            EditorSceneManager.SaveScene(scene);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();
            Debug.Log("[AI003][VEG] OpenWorld vegetation re-authored and saved");
        }

        private static bool IsForest(float slope, float m)
        {
            return m >= WorldTheme.ForestMoisture && slope <= ForestSlope;
        }

        private static bool IsSteppe(float slope, float m)
        {
            return m <= WorldTheme.SteppeMoisture && slope <= Mathf.Min(SteppeSlope, NoTreeSlope);
        }

        private static bool IsSnow(WorldData data, float h)
        {
            return h > WorldTheme.SnowLineMeters;
        }

        private static bool IsRockBand(float h)
        {
            return h >= 100f && h <= WorldTheme.SnowLineMeters;
        }

        private delegate bool Rule(float height, float up, float slope, float moisture, float hash);

        /// <summary>
        /// Walks a jittered lattice, keeps the candidates that satisfy the rule, and bakes
        /// them into one combined mesh asset. Returns the instance count.
        /// </summary>
        private static int Scatter(WorldData data, float[] moisture, GameObject root, string species,
            float spacing, Color tint, Rule rule, out Mesh mesh)
        {
            mesh = null;
            var source = LoadModelMesh(species);
            if (source == null)
            {
                Debug.LogWarning($"[AI003][VEG] model {species} not found under {ModelDir}");
                return 0;
            }

            float half = data.SizeMeters * 0.5f;
            var matrices = new List<Matrix4x4>();
            int steps = Mathf.FloorToInt(data.SizeMeters / spacing);

            for (int iz = 0; iz <= steps; iz++)
            {
                for (int ix = 0; ix <= steps; ix++)
                {
                    float hash = Hash01(ix, iz, species.Length);
                    float jx = (Hash01(ix, iz, 17) - 0.5f) * spacing * 0.9f;
                    float jz = (Hash01(ix, iz, 41) - 0.5f) * spacing * 0.9f;
                    float x = -half + ix * spacing + jx;
                    float z = -half + iz * spacing + jz;
                    if (x < -half || z < -half || x > half || z > half)
                    {
                        continue;
                    }

                    float h = data.HeightAt(x, z);
                    if (h < 0.5f)
                    {
                        continue;
                    }

                    Vector3 n = data.NormalAt(
                        Mathf.Clamp((int)((x + half) / data.CellSize), 0, data.Resolution - 1),
                        Mathf.Clamp((int)((z + half) / data.CellSize), 0, data.Resolution - 1));
                    float up = Mathf.Clamp01(n.y);
                    float slope = Mathf.Sqrt(Mathf.Max(0f, 1f - up * up)) / Mathf.Max(up, 0.001f);

                    float m = WorldTheme.SampleMoistureAt(moisture, data, x, z);
                    int cx = Mathf.Clamp((int)((x + half) / data.CellSize), 0, data.Resolution - 1);
                    int cz = Mathf.Clamp((int)((z + half) / data.CellSize), 0, data.Resolution - 1);
                    if (data.Biomes[cz * data.Resolution + cx] != 2 && !species.StartsWith("snow_rock"))
                    {
                        continue;
                    }
                    if (!rule(h, up, slope, m, hash))
                    {
                        continue;
                    }

                    float yaw = Hash01(ix, iz, 73) * 360f;
                    float scale = 0.85f + Hash01(ix, iz, 97) * 0.3f;
                    matrices.Add(Matrix4x4.TRS(new Vector3(x, h, z),
                        Quaternion.Euler(0f, yaw, 0f), Vector3.one * scale));
                }
            }

            if (matrices.Count == 0)
            {
                return 0;
            }

            // The import scale is the one number that can silently sink the whole layer
            // (a cm-authored FBX under a 1 m world made every tree 4 cm); print it.
            float srcHeight = source.bounds.size.y;
            Debug.Log($"[AI003][VEG] {species} srcHeight={srcHeight:F3} m instances={matrices.Count} " +
                      $"instanceHeight={srcHeight * 0.85f:F2}..{srcHeight * 1.15f:F2} m (scale 0.85..1.15)");

            mesh = Combine(species, source, matrices);
            var materials = LoadMaterials(species, source.subMeshCount, tint);
            EnsureBake(root, species, mesh, materials);
            return matrices.Count;
        }

        /// <summary>
        /// Reuses the species GameObject when it already exists: recreating it renumbers
        /// the scene every bake (202 lines of churn measured across two identical runs).
        /// </summary>
        private static void EnsureBake(GameObject root, string species, Mesh mesh, Material[] materials)
        {
            var existing = root.transform.Find(species);
            var go = existing != null ? existing.gameObject : new GameObject(species);
            if (existing == null)
            {
                go.transform.SetParent(root.transform, false);
            }

            var filter = go.GetComponent<MeshFilter>();
            if (filter == null)
            {
                filter = go.AddComponent<MeshFilter>();
            }
            filter.sharedMesh = mesh;

            var renderer = go.GetComponent<MeshRenderer>();
            if (renderer == null)
            {
                renderer = go.AddComponent<MeshRenderer>();
            }
            renderer.sharedMaterials = materials;
            renderer.shadowCastingMode = ShadowCastingMode.On;
            renderer.receiveShadows = true;
        }

        /// <summary>
        /// Fixed count of umbrella acacias inside a circle, gold-angle spiral so the
        /// stand never clumps. Points that fail the steppe rule are skipped.
        /// </summary>
        private static int PlaceAcacia(WorldData data, float[] moisture, GameObject root,
            Vector3[] centers, float[] radii, int[] counts)
        {
            var source = LoadModelMesh("acacia");
            if (source == null)
            {
                Debug.LogWarning("[AI003][VEG] model acacia not found");
                return 0;
            }

            float half = data.SizeMeters * 0.5f;
            var matrices = new List<Matrix4x4>();
            const float golden = 2.399963f;

            for (int anchor = 0; anchor < centers.Length; anchor++)
            {
                Vector3 center = centers[anchor];
                float radius = radii[anchor];
                int count = counts[anchor];

                for (int i = 0; i < count * 4 && CountInCircle(matrices, center, radius) < count; i++)
                {
                    float r = radius * Mathf.Sqrt((i + 0.5f) / (count * 4f));
                    float a = i * golden;
                    float x = center.x + Mathf.Cos(a) * r;
                    float z = center.z + Mathf.Sin(a) * r;
                    float h = data.HeightAt(x, z);
                    if (h < 0.5f)
                    {
                        continue;
                    }

                    int cx = Mathf.Clamp((int)((x + half) / data.CellSize), 0, data.Resolution - 1);
                    int cz = Mathf.Clamp((int)((z + half) / data.CellSize), 0, data.Resolution - 1);
                    if (data.Biomes[cz * data.Resolution + cx] != 2)
                    {
                        continue;
                    }

                    Vector3 n = data.NormalAt(cx, cz);
                    float up = Mathf.Clamp01(n.y);
                    float slope = Mathf.Sqrt(Mathf.Max(0f, 1f - up * up)) / Mathf.Max(up, 0.001f);
                    // Fixed-count landmark: the anchor must end up with acacias even where
                    // the moisture block reads wetter than the steppe threshold.
                    if (slope > SteppeSlope)
                    {
                        continue;
                    }

                    float yaw = Hash01(i, 7, 53 + anchor) * 360f;
                    float scale = 0.9f + Hash01(i, 11, 29 + anchor) * 0.25f;
                    matrices.Add(Matrix4x4.TRS(new Vector3(x, h, z), Quaternion.Euler(0f, yaw, 0f),
                        Vector3.one * scale));
                }
            }

            if (matrices.Count == 0)
            {
                return 0;
            }

            float acaciaHeight = source.bounds.size.y;
            Debug.Log($"[AI003][VEG] acacia srcHeight={acaciaHeight:F3} m instances={matrices.Count} " +
                      $"instanceHeight={acaciaHeight * 0.9f:F2}..{acaciaHeight * 1.15f:F2} m (scale 0.9..1.15)");

            Combine("acacia", source, matrices);
            var materials = LoadMaterials("acacia", source.subMeshCount, new Color(0.30f, 0.27f, 0.16f));
            var mesh = AssetDatabase.LoadAssetAtPath<Mesh>($"{MeshDir}/acacia.asset");
            EnsureBake(root, "acacia", mesh, materials);
            return matrices.Count;
        }

        private static int CountInCircle(List<Matrix4x4> matrices, Vector3 center, float radius)
        {
            float r2 = radius * radius;
            int n = 0;
            foreach (var m in matrices)
            {
                Vector3 p = m.GetColumn(3);
                float dx = p.x - center.x;
                float dz = p.z - center.z;
                if (dx * dx + dz * dz <= r2)
                {
                    n++;
                }
            }
            return n;
        }

        private static Mesh LoadModelMesh(string species)
        {
            string path = $"{ModelDir}/{species}/{species}_LOD0.fbx";
            var model = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (model == null)
            {
                return null;
            }
            var filter = model.GetComponentInChildren<MeshFilter>();
            return filter != null ? filter.sharedMesh : null;
        }

        private static Mesh Combine(string species, Mesh source, List<Matrix4x4> instances)
        {
            Vector3[] sv = source.vertices;
            Vector3[] sn = source.normals;
            Vector2[] su = source.uv;
            Vector2[] su2 = source.uv2;

            // Trees and rocks carry two submeshes (trunk + canopy, rock + snow cap).
            // Taking source.triangles flattened them into one slot and the canopy was
            // drawn with the bark material; keep one index list per source submesh.
            int subCount = Mathf.Max(1, source.subMeshCount);
            int[][] srcTris = new int[subCount][];
            for (int s = 0; s < subCount; s++)
            {
                srcTris[s] = source.GetTriangles(s);
            }

            var verts = new List<Vector3>(instances.Count * sv.Length);
            var normals = new List<Vector3>(instances.Count * sn.Length);
            var uvs = new List<Vector2>(instances.Count * su.Length);
            var uvs2 = new List<Vector2>(instances.Count * su.Length);
            var subTris = new List<int>[subCount];
            for (int s = 0; s < subCount; s++)
            {
                subTris[s] = new List<int>(instances.Count * srcTris[s].Length);
            }

            for (int i = 0; i < instances.Count; i++)
            {
                Matrix4x4 m = instances[i];
                int baseIndex = verts.Count;
                for (int v = 0; v < sv.Length; v++)
                {
                    verts.Add(m.MultiplyPoint3x4(sv[v]));
                    normals.Add(m.MultiplyVector(sn[v]).normalized);
                    // UV0 gets the WORLD-METRE set (UV1 of the source); the material then
                    // scales it by 1/tile. The new source meshes write real metres there.
                    uvs.Add(su2.Length > v ? su2[v] : Vector2.zero);
                    uvs2.Add(su.Length > v ? su[v] : Vector2.zero);
                }
                for (int s = 0; s < subCount; s++)
                {
                    int[] st = srcTris[s];
                    for (int t = 0; t < st.Length; t++)
                    {
                        subTris[s].Add(baseIndex + st[t]);
                    }
                }
            }

            void Fill(Mesh m)
            {
                m.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
                m.SetVertices(verts);
                m.SetNormals(normals);
                m.SetUVs(0, uvs);
                m.SetUVs(1, uvs2);
                m.subMeshCount = subCount;
                for (int s = 0; s < subCount; s++)
                {
                    m.SetTriangles(subTris[s], s);
                }
                m.RecalculateBounds();
                // The canopy materials sample _BumpMap; without tangents the normal map
                // is silently dropped by URP.
                m.RecalculateTangents();
            }

            string path = $"{MeshDir}/{species}.asset";
            var existing = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (existing == null)
            {
                var mesh = new Mesh { name = species };
                Fill(mesh);
                AssetDatabase.CreateAsset(mesh, path);
                return mesh;
            }

            // Keep the GUID so a re-run does not renumber the scene references.
            existing.Clear();
            Fill(existing);
            EditorUtility.SetDirty(existing);
            return existing;
        }

        private static Material[] LoadMaterials(string species, int subMeshCount, Color tint)
        {
            int count = Mathf.Max(1, subMeshCount);
            var materials = new Material[count];
            for (int s = 0; s < count; s++)
            {
                materials[s] = LoadOrCreateMaterial(species, s, count, tint);
            }
            return materials;
        }

        /// <summary>
        /// One material per submesh: slot 0 is {species}.mat (trunk / rock), slot 1 is
        /// {species}_1.mat (canopy / snow cap). Albedo, normal and roughness come from the
        /// species' texture set; UV0 is metres, so the map is scaled by 1/tile.
        /// </summary>
        private static Material LoadOrCreateMaterial(string species, int submesh, int subMeshCount, Color tint)
        {
            Directory.CreateDirectory(MaterialDir);
            string file = submesh == 0 ? species : $"{species}_{submesh}";
            string path = $"{MaterialDir}/{file}.mat";
            var material = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (material == null)
            {
                var shader = Shader.Find("Universal Render Pipeline/Lit");
                material = new Material(shader) { name = file };
                AssetDatabase.CreateAsset(material, path);
            }

            material.SetColor("_BaseColor", Color.white);
            material.SetFloat("_Metallic", 0f);
            material.SetFloat("_Smoothness", 0.30f);

            string set = subMeshCount > 1 ? TextureSet(species, submesh) : TextureSet(species);
            float tile = subMeshCount > 1 ? TileMeters(species, submesh) : TileMeters(species);
            var albedo = AssetDatabase.LoadAssetAtPath<Texture2D>(
                $"{TextureDir}/{set}/{set}_albedo_1024.png");
            if (albedo != null)
            {
                material.SetTexture("_BaseMap", albedo);
                material.SetTextureScale("_BaseMap", new Vector2(1f / tile, 1f / tile));
            }
            else
            {
                material.SetColor("_BaseColor", tint);
            }

            // Normal maps only sample when the keyword is on; Combine() writes tangents.
            var normal = AssetDatabase.LoadAssetAtPath<Texture2D>(
                $"{TextureDir}/{set}/{set}_normal_1024.png");
            if (normal != null)
            {
                material.SetTexture("_BumpMap", normal);
                material.SetFloat("_BumpScale", 0.8f);
                material.EnableKeyword("_NORMALMAP");
            }
            else
            {
                material.DisableKeyword("_NORMALMAP");
            }

            // Grass and bush cards: cutout, double sided (贴图 spec: alpha clip 0.5).
            bool cutout = species.StartsWith("grass") || species.StartsWith("bush");
            if (cutout)
            {
                material.SetFloat("_AlphaClip", 1f);
                material.SetFloat("_Cutoff", 0.5f);
                material.SetFloat("_Cull", 0f);
                material.SetFloat("_Surface", 0f);
                material.SetFloat("_Blend", 0f);
                material.SetFloat("_SrcBlend", 1f);
                material.SetFloat("_DstBlend", 0f);
                material.SetFloat("_ZWrite", 1f);
                material.EnableKeyword("_ALPHATEST_ON");
                material.DisableKeyword("_ALPHABLEND_ON");
                material.renderQueue = (int)RenderQueue.AlphaTest;
            }

            EditorUtility.SetDirty(material);
            return material;
        }

        private static string TextureSet(string species)
        {
            switch (species)
            {
                case "conifer":
                    return "canopy_needle";
                case "dead_tree":
                    return "bark";
                case "acacia":
                case "acacia_small":
                    return "canopy_umbrella";
                case "grass_tuft_a":
                case "grass_tuft_b":
                    return "grass_tuft";
                case "bush_a":
                case "bush_b":
                    return "bush_leaf";
                default:
                    return "rock_cliff";
            }
        }

        /// <summary>Texture set for a two-material species: slot 0 bark/rock, slot 1 cap.</summary>
        private static string TextureSet(string species, int submesh)
        {
            if (submesh == 0)
            {
                return species.StartsWith("snow_rock") ? "rock_cliff" : "bark";
            }
            switch (species)
            {
                case "conifer":
                    return "canopy_needle";
                case "acacia":
                case "acacia_small":
                    return "canopy_umbrella";
                default:
                    return "snow";
            }
        }

        private static float TileMeters(string species, int submesh)
        {
            if (submesh > 0)
            {
                return species.StartsWith("snow_rock") ? 1f : 2.5f;
            }
            return TileMeters(species);
        }

        private static float TileMeters(string species)
        {
            if (species.StartsWith("snow_rock") || species.StartsWith("grass") || species.StartsWith("bush"))
            {
                return 1f;
            }
            return 2.5f;
        }

        private static float Hash01(int x, int z, int salt)
        {
            unchecked
            {
                uint h = (uint)(x * 73856093) ^ (uint)(z * 19349663) ^ (uint)(salt * 83492791);
                h ^= h >> 13;
                h *= 0x85ebca6b;
                h ^= h >> 16;
                return (h & 0xFFFFFF) / 16777215f;
            }
        }
    }
}
